#!/usr/bin/env bash
# Generated by scgui Designer — build with gcc/clang (CMake not required).
# Edit SCGUI_SDL2_DIR below, or: export SCGUI_SDL2_DIR=/path/to/sdl2
# Widget features come from sc_config.h (project config), not -D here.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd)"
SCGUI_SDL2_DIR="${SCGUI_SDL2_DIR:-}"
if [[ -z "$SCGUI_SDL2_DIR" ]]; then
  SCGUI_SDL2_DIR="$ROOT/sdl2"
fi
CC="${CC:-gcc}"
OUT_DIR="$ROOT/build"
OUT="$OUT_DIR/scgui"

if [[ ! -f "$SCGUI_SDL2_DIR/include/SDL2/SDL.h" ]]; then
  echo "SDL2 headers not found: $SCGUI_SDL2_DIR/include/SDL2/SDL.h" >&2
  echo "Set SCGUI_SDL2_DIR to your SDL2 SDK root and retry." >&2
  exit 1
fi

mkdir -p "$OUT_DIR"
shopt -s nullglob
SOURCES=(main.c sc_sdl2.c)
SOURCES+=("$ROOT"/src/*.c)
SOURCES+=("$ROOT"/src/widget/*.c)
SOURCES+=("$ROOT"/src/third_party/qrcode/*.c)
SOURCES+=("$ROOT"/generated/*.c)
SOURCES+=("$ROOT"/generated/images/*.c)
SOURCES+=("$ROOT"/generated/fonts/*.c)

echo "Building $OUT with $CC ..."
"$CC" \
  -std=c99 -O2 -Wall -Wno-unused-parameter \
  -ffunction-sections -fdata-sections \
  -I"$ROOT" \
  -I"$ROOT/src" \
  -I"$ROOT/generated" \
  -I"$ROOT/generated/images" \
  -I"$ROOT/generated/fonts" \
  -I"$SCGUI_SDL2_DIR/include" \
  -L"$SCGUI_SDL2_DIR/lib" \
  "${SOURCES[@]}" \
  -Wl,--gc-sections \
  -lSDL2main -lSDL2 \
  -o "$OUT"

if [[ -f "$SCGUI_SDL2_DIR/bin/SDL2.dll" ]]; then
  cp -f "$SCGUI_SDL2_DIR/bin/SDL2.dll" "$OUT_DIR/SDL2.dll"
elif [[ -f "$SCGUI_SDL2_DIR/lib/libSDL2.dylib" ]]; then
  :
fi
echo "Build complete: $OUT"
